import {generate,reconcile,exportMarkdown,SANDBOX,validateSource} from './core.mjs';
const $=s=>document.querySelector(s), clone=x=>structuredClone(x), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fixture=await(await fetch('./fixture.json')).json();
let state,view='front',activity='all';
const fresh=()=>({source:clone(fixture),generated:generate(fixture),draft:generate(fixture),reviewed:[],baseline:null,conflicts:[],approved:false});
try{state=JSON.parse(localStorage.getItem('lesson-studio-v1'));if(!state?.draft||!state?.source)state=fresh();}catch{state=fresh();}
const persist=()=>{try{localStorage.setItem('lesson-studio-v1',JSON.stringify(state));}catch{notice('Browser storage is full or unavailable. Export a backup to preserve your work.');}};
function notice(s){$('#notice').textContent=s;}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const fields=[['teacherOverview','Teacher overview'],['studentOverview','Student overview'],['objectives','Objectives'],['preparation','Preparation'],['vocabulary','Vocabulary'],['purpose','Purpose'],['assessmentOpportunities','Assessment opportunities']];
const requiredIds=()=>['title',...fields.map(([k])=>k),'resources',...state.draft.activities.map(a=>'activity:'+a.id),...state.draft.sections.map(s=>s.id)];
const fieldText=(k,v)=>k==='objectives'?(v||[]).join('\n'):k==='vocabulary'?(v||[]).map(t=>typeof t==='string'?t:`${t.word}: ${t.definition}`).join('\n'):v||'';
const changed=key=>{state.reviewed=state.reviewed.filter(x=>x!==key);state.approved=false;persist();updateSummary();};
function reviewControl(id){return `<label class="review-toggle"><input type="checkbox" data-review="${esc(id)}" ${state.reviewed.includes(id)?'checked':''}> Reviewed</label>`;}
function preview(text){return esc(text).replace(/&lt;i class=&quot;([^&]+)&quot; aria-hidden=&quot;true&quot;&gt;&lt;\/i&gt;/g,'<span class="icon-preview" title="$1">◆</span>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>');}
function updateSummary(){
 const p=state.draft,done=requiredIds().filter(id=>state.reviewed.includes(id)).length,total=requiredIds().length;
 $('#title').textContent=p.title;$('#subtitle').textContent=`${p.course||'Lesson workspace'} · ${p.duration} minutes · source snapshot`;
 $('#metrics').innerHTML=`<div class="metric"><strong>${p.sections.length}</strong><span>Teaching sections</span></div><div class="metric"><strong>${p.resources.length}</strong><span>Linked resources</span></div><div class="metric"><strong>${p.sections.reduce((n,s)=>n+s.callouts.length,0)}</strong><span>Teaching callouts</span></div><div class="metric"><strong>${done} / ${total}</strong><span>Items reviewed</span></div>`;
 $('#review-state').textContent=state.approved?'Approved locally':state.conflicts.length?`${state.conflicts.length} conflicts to resolve`:'Draft · review needed';$('#review-state').className='pill'+(state.approved?' approved':'');
 $('#approve').disabled=done!==total||state.conflicts.length>0;
 $('#approve').textContent=state.approved?'Approved locally':'Approve reviewed draft';
 $('#warnings').innerHTML=(state.source.deckUrl===fixture.deckUrl?'<div class="warning"><strong>Known source correction.</strong> The official lesson’s Slides resource points to the answer key. This draft uses the confirmed presentation link. Official materials are unchanged.</div>':'')+p.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('');
 $('#nav').innerHTML=[['front','Front matter',7],['guide','Teaching Guide',p.sections.length],['resources','Resources',p.resources.length],['revisions','Revision review',state.conflicts.length]].map(([id,label,count])=>`<button data-view="${id}" class="${view===id?'active':''}">${label}<span>${count}</span></button>`).join('');
}
function render(){
 updateSummary();const p=state.draft;
 const titles={front:['Front matter','Keep the teacher and student experience distinct.'],guide:['Teaching Guide','Review source notes, transformations, and lesson-only guidance.'],resources:['Resources','Check each destination, type, and intended audience.'],revisions:['Revision review','Keep approved work. Resolve new changes deliberately.']};
 $('#view-title').textContent=titles[view][0];$('#view-description').textContent=titles[view][1];
 if(view==='front'){
  $('#content').innerHTML=`<div class="card"><div class="card-head"><h3>Lesson title</h3>${reviewControl('title')}</div><div class="pane"><label for="lesson-title">Title</label><input id="lesson-title" class="editor" value="${esc(p.title)}"></div></div>`+fields.map(([k,label])=>`<article class="card"><div class="card-head"><h3>${label}</h3>${reviewControl(k)}</div><div class="compare"><div class="pane"><div class="pane-label">Notion brief · source</div><div class="source-text">${esc(fieldText(k,state.source[k]))||'<em>No content supplied. Review whether this is intentional.</em>'}</div></div><div class="pane"><div class="pane-label">Level Builder · editable draft</div><label for="field-${k}" class="muted">${k==='objectives'?'One objective per line':k==='vocabulary'?'One term and definition per line':label+' Markdown'}</label><textarea id="field-${k}" class="editor" data-field="${k}" rows="${k.includes('Overview')?7:4}">${esc(fieldText(k,p.frontMatter[k]))}</textarea><button data-copy-field="${k}">Copy field</button></div></div></article>`).join('');
 }else if(view==='guide'){
  $('#content').innerHTML=`<div class="section-nav"><button data-activity="all" class="${activity==='all'?'active':''}">All activities</button>${p.activities.map(a=>`<button data-activity="${esc(a.id)}" class="${activity===a.id?'active':''}">${esc(a.title)} · ${a.duration} min</button>`).join('')}</div>`+p.activities.filter(a=>activity==='all'||activity===a.id).map(a=>`<article class="card"><div class="card-head"><h3>${esc(a.title)} · activity settings</h3>${reviewControl('activity:'+a.id)}</div><div class="pane row"><div><label>Activity title<input class="editor" data-activity-field="title" data-id="${esc(a.id)}" value="${esc(a.title)}"></label></div><div><label>Duration in minutes<input class="editor" type="number" min="0" data-activity-field="duration" data-id="${esc(a.id)}" value="${a.duration}"></label></div></div></article>`+p.sections.filter(s=>s.activityId===a.id).map(s=>sectionCard(s)).join('')).join('');
 }else if(view==='resources'){
  $('#content').innerHTML=`<article class="card"><div class="card-head"><h3>Lesson resource records</h3>${reviewControl('resources')}</div><div class="pane"><p class="muted">Audience is part of each resource record. Answer keys must remain teacher-only. Edit the records below, then apply and review.</p><label for="resource-json">Resource records (JSON)</label><textarea id="resource-json" class="editor" rows="12">${esc(JSON.stringify(p.resources,null,2))}</textarea><button id="apply-resources">Apply resource edits</button></div>${p.resources.map(r=>`<div class="resource"><h3>${esc(r.name)}</h3><span class="pill">${esc(r.type)}</span><span class="pill">${esc(r.audience)}</span><br><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.url)}</a></div>`).join('')}</article>`;
 }else{
  $('#content').innerHTML=`<div class="card review-card"><h3>${state.baseline?'An approved baseline is saved in this browser.':'No approved baseline yet.'}</h3><p>Review each item, then approve the draft to establish a local baseline. Approval does not publish. Import revised sources to compare against that baseline while retaining your edits.</p><p>Incoming source deletions and conflicting changes always need a decision. A field kept intentionally will not be flagged again for the same source snapshot.</p><p class="muted">Current destination content is not connected. This version compares imported sources against the local draft; a live three-way destination comparison remains future work.</p></div>`+(state.conflicts.length?state.conflicts.map((c,i)=>`<article class="card review-card"><h3>${esc(c.label)}</h3><div class="compare"><div class="pane diff-old"><div class="pane-label">Your current draft</div><pre>${esc(display(c.current))}</pre></div><div class="pane diff-new"><div class="pane-label">Incoming source</div><pre>${esc(display(c.incoming))}</pre></div></div><div class="actions"><button data-resolve="keep" data-index="${i}">Keep current</button><button data-resolve="edit" data-index="${i}">Edit manually</button><button data-resolve="incoming" data-index="${i}">${c.incoming==null?'Remove explicitly':'Use incoming'}</button></div></article>`).join(''):'<div class="card empty">No unresolved source conflicts.</div>');
 }
}
function sectionCard(s){return `<article class="card"><div class="card-head"><div><h3>${esc(s.title||'Untitled section')}</h3><small>Slide ${s.slide}${s.duration?' · '+s.duration+' min':''}</small></div>${reviewControl(s.id)}</div><div class="compare"><div class="pane"><div class="pane-label">Speaker notes · source slide ${s.slide}</div><div class="source-text">${esc(s.sourceNotes)}</div><div class="chips">${s.changes.map(c=>`<span class="chip">${esc(c.from)} ${c.kind==='removed'?'removed':'→ '+c.to}</span>`).join('')}</div></div><div class="pane"><div class="pane-label">Level Builder · editable draft</div><div class="row"><div><label>Section title<input class="editor" data-section="${esc(s.id)}" data-prop="title" value="${esc(s.title)}"></label></div><div><label>Minutes<input class="editor" type="number" min="0" data-section="${esc(s.id)}" data-prop="duration" value="${s.duration}"></label></div></div><label class="inline-check"><input type="checkbox" data-section="${esc(s.id)}" data-prop="remarks" ${s.remarks?'checked':''}> Remarks <span class="muted">(rendering not yet verified)</span></label><label for="body-${esc(s.id)}">Teaching guidance · Markdown and icon HTML</label><textarea id="body-${esc(s.id)}" class="editor" rows="9" data-section="${esc(s.id)}" data-prop="body">${esc(s.body)}</textarea><button data-copy-section="${esc(s.id)}">Copy guidance</button><details><summary class="muted">Text preview (icons shown as markers)</summary><div class="preview">${preview(s.body)}</div></details>${s.callouts.map((c,i)=>`<div class="callout"><label for="callout-${esc(s.id)}-${i}">${esc(c.type)}</label><textarea id="callout-${esc(s.id)}-${i}" class="editor" rows="4" data-callout="${i}" data-section="${esc(s.id)}">${esc(c.body)}</textarea></div>`).join('')}${s.progression?`<div class="level"><strong>${esc(s.progression.title)}</strong><br>${s.progression.levels.map(l=>`Level ${l.number} · ${esc(l.key)}`).join('<br>')}<br><span class="muted">Preserved association metadata; not published.</span></div>`:''}</div></div></article>`;}
function display(v){return v==null?'Source removed this item':typeof v==='string'?v:JSON.stringify(v,null,2);}
function setConflictValue(c,v){if(c.kind==='section'){const i=state.draft.sections.findIndex(s=>s.id===c.key);if(v==null){if(i>=0)state.draft.sections.splice(i,1);}else if(i>=0)state.draft.sections[i]=clone(v);else state.draft.sections.push(clone(v));}else if(c.kind==='front')state.draft.frontMatter[c.key]=clone(v);else state.draft[c.key]=clone(v);}
function mergeSource(source){
 if(state.conflicts.length)throw Error('Resolve the current source conflicts before importing another revision.');
 const next=generate(source),base=state.generated;const conflicts=[];let updates=0;
 function merge(kind,key,label,old,cur,inc){const r=reconcile(old,cur,inc);if(r.status==='conflict'){conflicts.push({kind,key,label,current:clone(cur),incoming:clone(inc)});}else{setConflictValue({kind,key},r.value);if(r.status==='updated')updates++;}}
 for(const [k,label] of fields)merge('front',k,label,base.frontMatter[k],state.draft.frontMatter[k],next.frontMatter[k]);
 for(const k of ['title','course','resources','activities'])merge('root',k,k,base[k],state.draft[k],next[k]);
 const ids=new Set([...base.sections.map(s=>s.id),...state.draft.sections.map(s=>s.id),...next.sections.map(s=>s.id)]);
 for(const id of ids)merge('section',id,`Teaching section · ${id}`,base.sections.find(s=>s.id===id)||null,state.draft.sections.find(s=>s.id===id)||null,next.sections.find(s=>s.id===id)||null);
 state.source=clone(source);state.generated=clone(next);state.draft.warnings=clone(next.warnings);state.draft.duration=state.draft.activities.reduce((n,a)=>n+a.duration,0);state.conflicts=conflicts;
 if(updates||conflicts.length){state.reviewed=[];state.approved=false;}
 persist();view=conflicts.length?'revisions':view;render();notice(`${updates} source updates applied. ${conflicts.length} conflicts need your decision. Local edits are preserved.`);
}
async function copy(text){try{await navigator.clipboard.writeText(text);notice('Copied to clipboard.');}catch{notice('Clipboard access unavailable. Select the text and copy it manually.');}}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.view){view=b.dataset.view;render();}
 if(b.dataset.activity){activity=b.dataset.activity;render();}
 if(b.dataset.copyField)await copy(fieldText(b.dataset.copyField,state.draft.frontMatter[b.dataset.copyField]));
 if(b.dataset.copySection)await copy(state.draft.sections.find(s=>s.id===b.dataset.copySection).body);
 if(b.dataset.resolve){const i=Number(b.dataset.index),c=state.conflicts[i];if(b.dataset.resolve==='incoming')setConflictValue(c,c.incoming);state.conflicts.splice(i,1);state.approved=false;state.reviewed=[];persist();if(b.dataset.resolve==='edit')view=c.kind==='section'?'guide':c.key==='resources'?'resources':'front';render();notice(b.dataset.resolve==='edit'?'Current text retained. Edit it in the draft, then mark it reviewed.':'Conflict decision recorded.');}
 if(b.id==='apply-resources'){try{const resources=JSON.parse($('#resource-json').value);validateSource({...state.source,resources});state.draft.resources=resources;changed('resources');render();notice('Resource edits applied. Review audience and destinations.');}catch(err){notice(err.message);}}
});
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.id==='lesson-title'){state.draft.title=el.value;changed('title');}
 if(el.dataset.field){const k=el.dataset.field;state.draft.frontMatter[k]=['objectives','vocabulary'].includes(k)?el.value.split('\n').filter(x=>x.trim()):el.value;changed(k);}
 if(el.dataset.section){const s=state.draft.sections.find(s=>s.id===el.dataset.section);if(el.dataset.callout!==undefined)s.callouts[Number(el.dataset.callout)].body=el.value;else{const k=el.dataset.prop;s[k]=k==='remarks'?el.checked:k==='duration'?Math.max(0,Number(el.value)||0):el.value;}changed(s.id);}
 if(el.dataset.activityField){const a=state.draft.activities.find(a=>a.id===el.dataset.id);a[el.dataset.activityField]=el.dataset.activityField==='duration'?Math.max(0,Number(el.value)||0):el.value;state.draft.duration=state.draft.activities.reduce((n,a)=>n+a.duration,0);changed('activity:'+a.id);}
});
document.addEventListener('change',e=>{if(e.target.dataset.review){const id=e.target.dataset.review;state.reviewed=state.reviewed.filter(x=>x!==id);if(e.target.checked)state.reviewed.push(id);else state.approved=false;persist();updateSummary();}});
$('#sources').onclick=()=>{$('#source-input').value=JSON.stringify(state.source,null,2);$('#import-error').textContent='';$('#import-dialog').showModal();};
$('#source-file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>2_000_000){$('#import-error').textContent='Source file must be smaller than 2 MB.';return;}$('#source-input').value=await f.text();}};
$('#generate').onclick=()=>{try{const source=JSON.parse($('#source-input').value);validateSource(source);mergeSource(source);$('#import-dialog').close();}catch(err){$('#import-error').textContent=err.message;}};
$('#download-source').onclick=()=>download('lesson-source-template.json',JSON.stringify(fixture,null,2),'application/json');
$('#approve').onclick=()=>{if(requiredIds().every(x=>state.reviewed.includes(x))&&!state.conflicts.length){state.baseline=clone(state.draft);state.approved=true;persist();render();notice('Approved baseline saved locally. No Level Builder changes were made.');}};
$('#export').onclick=()=>{$('#export-status').textContent=state.approved?'This draft is approved locally.':'This export is an unapproved draft. '+state.conflicts.length+' unresolved conflicts.';$('#export-dialog').showModal();};
$('#md-export').onclick=()=>download('lesson-review.md',exportMarkdown(state.draft),'text/markdown');
$('#json-export').onclick=()=>download('lesson-review-package.json',JSON.stringify({schemaVersion:1,status:state.approved?'approved-locally':'draft',sandbox:SANDBOX,published:false,source:state.source,lesson:state.draft,baseline:state.baseline,conflicts:state.conflicts},null,2),'application/json');
$('#reset').onclick=()=>$('#reset-dialog').showModal();
$('#confirm-reset').onclick=()=>{state=fresh();persist();render();$('#reset-dialog').close();notice('Local workspace reset to the verified source snapshot.');};
render();
